from collections import deque

def get_components(grid, target_color):
    h, w = len(grid), len(grid[0])
    visited = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_color and (r,c) not in visited:
                comp = []
                q = deque([(r,c)])
                visited.add((r,c))

                while q:
                    cr, cc = q.popleft()
                    comp.append((cr,cc))

                    for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<h and 0<=nc<w:
                            if grid[nr][nc] == target_color and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                q.append((nr,nc))
                comps.append(comp)
    return comps

